import{_ as t,o as n,c as r,a2 as i}from"./chunks/framework.Buc7gXeZ.js";const b=JSON.parse('{"title":"Webhooks","description":"Andere Systeme automatisch über Änderungen in einem Grid informieren.","frontmatter":{"title":"Webhooks","description":"Andere Systeme automatisch über Änderungen in einem Grid informieren."},"headers":[],"relativePath":"integrationen/webhooks.md","filePath":"integrationen/webhooks.md","lastUpdated":1786092153000}'),o={name:"integrationen/webhooks.md"};function s(a,e,d,l,h,c){return n(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="webhooks" tabindex="-1">Webhooks <a class="header-anchor" href="#webhooks" aria-label="Permalink to &quot;Webhooks&quot;">​</a></h1><p>Ein <strong>Webhook</strong> benachrichtigt ein fremdes System, wenn in einem Grid etwas passiert.</p><p>Die Beschreibung in der Oberfläche:</p><blockquote><p><em>Webhooks sind automatische Nachrichten, die gesendet werden, wenn etwas passiert. Sie haben eine Nachricht oder Payload und werden an eine eindeutige URL gesendet.</em></p></blockquote><div class="warning custom-block"><p class="custom-block-title">Zwei Richtungen, zwei Orte</p><table tabindex="0"><thead><tr><th>Richtung</th><th>Wo eingerichtet</th></tr></thead><tbody><tr><td><strong>ApptiveGrid → Fremdsystem</strong></td><td>Space-Einstellungen → Webhooks — diese Seite</td></tr><tr><td><strong>Fremdsystem → ApptiveGrid</strong></td><td><a href="/docs/flows/webhook-trigger">Flow-Auslöser <em>Webhook</em></a></td></tr></tbody></table><p>Beide heißen „Webhook&quot;, tun aber Entgegengesetztes.</p></div><h2 id="webhook-anlegen" tabindex="-1">Webhook anlegen <a class="header-anchor" href="#webhook-anlegen" aria-label="Permalink to &quot;Webhook anlegen&quot;">​</a></h2><ol><li>Öffnen Sie <strong>Space Einstellungen → Webhooks</strong>.</li><li>Klicken Sie auf <strong>Webhook erstellen</strong>.</li><li>Vergeben Sie unter <strong>Name des Webhooks</strong> eine Bezeichnung. Vorgabe ist <em>Mein Webhook</em>.</li><li>Legen Sie unter <strong>Den Flow auslösen, wenn</strong> das Ereignis fest.</li><li>Tragen Sie die Ziel-URL ein und <strong>Speichern</strong> Sie.</li></ol><p>Über <strong>Bearbeiten</strong> und <strong>Löschen</strong> verwalten Sie bestehende Webhooks.</p><div class="tip custom-block"><p class="custom-block-title">Sprechend benennen</p><p>Bei mehreren Webhooks sagt „Mein Webhook&quot; nichts. Benennen Sie nach Ziel und Zweck — „Warenwirtschaft: neue Bestellung&quot;.</p></div><h2 id="ereignisse" tabindex="-1">Ereignisse <a class="header-anchor" href="#ereignisse" aria-label="Permalink to &quot;Ereignisse&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Ereignis</th><th>Auslöser</th><th>Zusätzlich wählen</th></tr></thead><tbody><tr><td><strong>Neuer Eintrag</strong></td><td>Ein Eintrag entsteht</td><td>Space, Grid</td></tr><tr><td><strong>Eintrag verändert</strong></td><td>Ein Eintrag wird geändert</td><td>Space, Grid</td></tr><tr><td><strong>Neuer Eintrag per Formular</strong></td><td>Ein Formular legt an</td><td>Space, Grid, Formular</td></tr><tr><td><strong>Eintrag verändert per Formular</strong></td><td>Ein Formular ändert</td><td>Space, Grid, Formular</td></tr></tbody></table><p>Über <strong>Space auswählen</strong>, <strong>Grid auswählen</strong>, <strong>Event auswählen</strong> und <strong>Formular auswählen</strong> grenzen Sie ein.</p><div class="warning custom-block"><p class="custom-block-title">Veraltete Ereignisse</p><p>Ältere Webhooks können Ereignisse verwenden, die im Dialog mit <strong>veraltet</strong> gekennzeichnet sind. Sie funktionieren weiter, sollten bei einer Überarbeitung aber ersetzt werden.</p></div><h2 id="webhook-oder-flow" tabindex="-1">Webhook oder Flow? <a class="header-anchor" href="#webhook-oder-flow" aria-label="Permalink to &quot;Webhook oder Flow?&quot;">​</a></h2><p>Beide reagieren auf dieselben Ereignisse. Der Unterschied:</p><table tabindex="0"><thead><tr><th></th><th>Webhook</th><th><a href="/docs/flows/was-ist-ein-flow">Flow</a></th></tr></thead><tbody><tr><td>Zweck</td><td>Rohdaten weitergeben</td><td>Etwas tun</td></tr><tr><td>Logik</td><td>keine</td><td>Bedingungen, Schleifen, mehrere Schritte</td></tr><tr><td>Empfänger</td><td>ein System</td><td>beliebig viele Aktionen</td></tr><tr><td>Voraussetzung</td><td>Empfänger kann JSON verarbeiten</td><td>–</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Für die meisten Fälle ist ein Flow der richtige Weg</p><p>Ein Webhook schickt nur Daten weiter. Wollen Sie <strong>filtern</strong> („nur bei Beträgen über 1000 €&quot;), <strong>anreichern</strong> oder <strong>mehrere Dinge</strong> auslösen, brauchen Sie einen Flow — dort ist der Schritt <strong>HTTP-Anfrage</strong> das Gegenstück zum Webhook, aber mit Logik davor.</p><p>Ein Webhook lohnt sich, wenn ein System schlicht jede Änderung mitbekommen soll.</p></div><h2 id="grenzen" tabindex="-1">Grenzen <a class="header-anchor" href="#grenzen" aria-label="Permalink to &quot;Grenzen&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Anzahl je Space ist tarifabhängig</p><p>Ist die Grenze erreicht, erscheint <em>Weitere Webhooks anlegen</em> mit einem Upgrade-Hinweis.</p></div><div class="warning custom-block"><p class="custom-block-title">Keine Zustellkontrolle in der Oberfläche</p><p>Anders als bei <a href="/docs/flows/durchlaufhistorie">Flow-Ausführungen</a> gibt es keine Historie, die zeigt, ob ein Webhook angekommen ist. Schlägt die Zustellung fehl, bemerken Sie das nur am Zielsystem.</p><p>Wo Nachvollziehbarkeit wichtig ist, ist ein Flow die bessere Wahl — dort sehen Sie jede Ausführung samt Fehlern.</p></div><h2 id="sicherheit" tabindex="-1">Sicherheit <a class="header-anchor" href="#sicherheit" aria-label="Permalink to &quot;Sicherheit&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">Die Ziel-URL bekommt Ihre Daten</p><p>Der Webhook sendet den Inhalt des Eintrags an die eingetragene Adresse. Prüfen Sie:</p><ul><li>Ist die Adresse korrekt und aktuell?</li><li>Wird über HTTPS übertragen?</li><li>Darf der Empfänger diese Daten überhaupt erhalten?</li></ul><p>Bei personenbezogenen Daten gehört das datenschutzrechtlich geprüft.</p></div><div class="tip custom-block"><p class="custom-block-title">Nicht mehr benötigte Webhooks entfernen</p><p>Ein Webhook feuert weiter, auch wenn das Zielsystem längst abgeschaltet ist. Sehen Sie die Liste regelmäßig durch — besonders nach Systemwechseln.</p></div><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/docs/integrationen/ueberblick">Überblick</a></li><li><a href="/docs/flows/webhook-trigger">Flow per Webhook starten</a></li><li><a href="/docs/flows/aktionen">Aktionen</a></li></ul>',25)])])}const u=t(o,[["render",s]]);export{b as __pageData,u as default};
